        return s.count('A') < 2 and "LLL" not in s

class Solution {
public:
    bool checkRecord(string s) {
        int aCount = 0;
        int lConsec = 0;
        for (char c : s) {
            if (c == 'A') {
                aCount++;
                if (aCount >= 2) return false;
            }
            if (c == 'L') {
                lConsec++;
                if (lConsec >= 3) return false;
            } else {
                lConsec = 0;
            }
        }
        return true;
    }
};

class Solution {
    public boolean checkRecord(String s) {
        int aCount = 0;
        int lConsec = 0;
        for (char c : s.toCharArray()) {
            if (c == 'A') {
                aCount++;
                if (aCount >= 2) return false;
            }
            if (c == 'L') {
                lConsec++;
                if (lConsec >= 3) return false;
            } else {
                lConsec = 0;
            }
        }
        return true;
    }
}

var checkRecord = function(s) {
    let aCount = 0;
    let lConsec = 0;
    for (let i = 0; i < s.length; i++) {
        if (s[i] === 'A') {
            aCount++;
            if (aCount >= 2) return false;
        }
        if (s[i] === 'L') {
            lConsec++;
            if (lConsec >= 3) return false;
        } else {
            lConsec = 0;
        }
    }
    return true;
};
